style.css:
@-moz-document domain("open.spotify.com") {
/* Fondo principal del sitio */
  body,
  .Root__main-view {
    background-color: #1e1e2f !important;
    color: #ffffff !important;
  }

  /* Oculta todo menos el player (opcional) */
  .Root__top-bar,
  .Root__nav-bar,
  .main-view-container__scroll-node,
  .Root__now-playing-bar__left,
  .Root__now-playing-bar__right {
    display: none !important;
  }

  /* Estiliza el reproductor inferior */
  .Root__now-playing-bar {
    background-color: #181818 !important;
    box-shadow: 0 0 20px rgba(0,0,0,0.4) !important;
    border-radius: 20px !important;
    margin: 50px auto !important;
    width: 400px !important;
    height: 100px !important;
    padding: 15px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    position: relative !important;
    z-index: 9999 !important;
  }

  /* Portada del álbum */
  .now-playing-bar__left img {
    width: 70px !important;
    height: 70px !important;
    border-radius: 10px !important;
    box-shadow: 0 0 10px rgba(0,0,0,0.6) !important;
  }

  /* Título y artista */
  .now-playing-bar__left .track-info__name,
  .now-playing-bar__left .track-info__artists {
    color: #fff !important;
    font-family: "Segoe UI", sans-serif !important;
  }

  .track-info__name {
    font-size: 15px !important;
    font-weight: 600 !important;
  }

  .track-info__artists {
    font-size: 12px !important;
    color: #b3b3b3 !important;
  }

  /* Botones de control */
  .player-controls__buttons button {
    filter: invert(100%) !important;
    opacity: 0.9 !important;
    transition: transform 0.2s ease !important;
  }

  .player-controls__buttons button:hover {
    transform: scale(1.2) !important;
    filter: invert(60%) sepia(1) saturate(5) hue-rotate(80deg) !important;
  }

  /* Barra de progreso (opcional: ocultar o personalizar) */
  .playback-bar {
    display: none !important;
  }
}
